'use strict';

// TEST-ONLY stand-in for the `pg` package, used solely to exercise the real
// service code against a real PostgreSQL in environments where npm packages
// cannot be installed. It speaks the PostgreSQL v3 wire protocol (trust auth,
// extended query protocol, text format) and mimics node-postgres' default
// type parsing. Production uses the real `pg` from package.json.

const net = require('node:net');

const parsers = new Map();
const types = { setTypeParser: (oid, fn) => parsers.set(oid, fn), getTypeParser: (oid) => parsers.get(oid) };

function parseArray(text, conv) {
  // Handles flat arrays of simple values (all this app uses).
  if (text === '{}') return [];
  return text.slice(1, -1).split(',').map((s) => (s === 'NULL' ? null : conv(s.replace(/^"|"$/g, ''))));
}

function parseValue(oid, text) {
  if (text === null) return null;
  if (parsers.has(oid)) return parsers.get(oid)(text);
  switch (oid) {
    case 16: return text === 't';
    case 21: case 23: case 26: return Number(text);
    case 700: case 701: return Number(text);
    case 114: case 3802: return JSON.parse(text);
    case 1082: return new Date(text + 'T00:00:00');
    case 1114: return new Date(text.replace(' ', 'T') + 'Z');
    case 1184: return new Date(text.replace(' ', 'T').replace(/([+-]\d\d)$/, '$1:00'));
    case 17: return Buffer.from(text.slice(2), 'hex');
    case 1005: case 1007: return parseArray(text, Number); // int2[] / int4[]
    case 1016: return parseArray(text, String); // int8[]: strings, like node-postgres
    case 1009: return parseArray(text, String);
    default: return text; // int8 (20) and numeric stay strings unless a parser is set
  }
}

function serialize(v) {
  if (v === null || v === undefined) return null;
  if (Buffer.isBuffer(v)) return '\\x' + v.toString('hex');
  if (v instanceof Date) return v.toISOString();
  if (Array.isArray(v)) return '{' + v.map((x) => (x === null ? 'NULL' : '"' + String(serialize(x)).replace(/"/g, '\\"') + '"')).join(',') + '}';
  if (typeof v === 'boolean') return v ? 't' : 'f';
  if (typeof v === 'object') return JSON.stringify(v);
  return String(v);
}

class PgError extends Error {
  constructor(fields) { super(fields.M); Object.assign(this, { code: fields.C, detail: fields.D, constraint: fields.n }); }
}

class Client {
  constructor(cfg) {
    const u = new URL(cfg.connectionString);
    this.cfg = { host: u.hostname, port: Number(u.port || 5432), user: decodeURIComponent(u.username), database: u.pathname.slice(1) };
    this.buf = Buffer.alloc(0);
    this.queue = Promise.resolve();
  }

  connect() {
    return new Promise((resolve, reject) => {
      const host = this.cfg.host;
      this.sock = host.startsWith('/') ? net.connect(`${host}/.s.PGSQL.${this.cfg.port}`) : net.connect(this.cfg.port, host);
      this.sock.on('error', reject);
      this.sock.on('data', (d) => { this.buf = Buffer.concat([this.buf, d]); this.pump(); });
      const params = Buffer.from(`user\0${this.cfg.user}\0database\0${this.cfg.database}\0client_encoding\0UTF8\0\0`);
      const head = Buffer.alloc(8); head.writeInt32BE(8 + params.length); head.writeInt32BE(196608, 4);
      this.waiter = { onMsg: (t, b) => {
        if (t === 'R' && b.readInt32BE(0) !== 0) reject(new Error('only trust auth is supported by the test shim'));
        if (t === 'E') reject(new PgError(errFields(b)));
        if (t === 'Z') { this.waiter = null; resolve(); }
      } };
      this.sock.write(Buffer.concat([head, params]));
    });
  }

  pump() {
    while (this.buf.length >= 5) {
      const len = this.buf.readInt32BE(1);
      if (this.buf.length < len + 1) return;
      const type = String.fromCharCode(this.buf[0]);
      const body = this.buf.subarray(5, len + 1);
      this.buf = this.buf.subarray(len + 1);
      if (this.waiter) this.waiter.onMsg(type, body);
    }
  }

  query(text, params) {
    const run = () => new Promise((resolve, reject) => {
      const result = { rows: [], rowCount: 0, fields: [] };
      let err = null; let fields = [];
      this.waiter = { onMsg: (t, b) => {
        if (t === 'T') {
          const n = b.readInt16BE(0); let o = 2; fields = [];
          for (let i = 0; i < n; i++) {
            const end = b.indexOf(0, o); const name = b.toString('utf8', o, end); o = end + 1;
            const oid = b.readInt32BE(o + 6); o += 18;
            fields.push({ name, oid });
          }
          result.fields = fields; result.rows = [];
        } else if (t === 'D') {
          const n = b.readInt16BE(0); let o = 2; const row = {};
          for (let i = 0; i < n; i++) {
            const l = b.readInt32BE(o); o += 4;
            const text = l === -1 ? null : b.toString('utf8', o, o + l); if (l > 0) o += l;
            row[fields[i].name] = parseValue(fields[i].oid, text);
          }
          result.rows.push(row);
        } else if (t === 'C') {
          const tag = b.toString('utf8', 0, b.length - 1);
          const m = /(\d+)$/.exec(tag); result.rowCount = m ? Number(m[1]) : 0; result.command = tag.split(' ')[0];
        } else if (t === 'E') {
          err = new PgError(errFields(b));
        } else if (t === 'Z') {
          this.waiter = null;
          if (err) reject(err); else resolve(result);
        }
      } };
      // Like node-postgres: no values → simple protocol (allows multi-statement text).
      if (!params || !params.length) { this.sock.write(msg('Q', cstr(text))); return; }
      const vals = (params || []).map(serialize);
      const bindParts = [cstr(''), cstr(''), i16(0), i16(vals.length)];
      for (const v of vals) {
        if (v === null) bindParts.push(i32(-1));
        else { const bb = Buffer.from(v, 'utf8'); bindParts.push(i32(bb.length), bb); }
      }
      bindParts.push(i16(1), i16(0));
      this.sock.write(Buffer.concat([
        msg('P', Buffer.concat([cstr(''), cstr(text), i16(0)])),
        msg('B', Buffer.concat(bindParts)),
        msg('D', Buffer.concat([Buffer.from('P'), cstr('')])),
        msg('E', Buffer.concat([cstr(''), i32(0)])),
        msg('S', Buffer.alloc(0)),
      ]));
    });
    const p = this.queue.then(run, run);
    this.queue = p.catch(() => {});
    return p;
  }

  release() { this.pool._release(this); }
  end() { this.sock?.end(); }
}

function errFields(b) {
  const f = {}; let o = 0;
  while (o < b.length && b[o] !== 0) { const k = String.fromCharCode(b[o]); const end = b.indexOf(0, o + 1); f[k] = b.toString('utf8', o + 1, end); o = end + 1; }
  return f;
}
const cstr = (s) => Buffer.from(s + '\0', 'utf8');
const i16 = (n) => { const b = Buffer.alloc(2); b.writeInt16BE(n); return b; };
const i32 = (n) => { const b = Buffer.alloc(4); b.writeInt32BE(n); return b; };
function msg(type, body) { const h = Buffer.alloc(5); h.write(type); h.writeInt32BE(body.length + 4, 1); return Buffer.concat([h, body]); }

class Pool {
  constructor(cfg) { this.cfg = cfg; this.idle = []; this.all = []; }
  on() {}
  async connect() {
    let c = this.idle.pop();
    if (!c) { c = new Client(this.cfg); c.pool = this; await c.connect(); this.all.push(c); }
    return c;
  }
  _release(c) { this.idle.push(c); }
  async query(text, params) {
    const c = await this.connect();
    try { return await c.query(text, params); } finally { c.release(); }
  }
  async end() { for (const c of this.all) c.end(); }
}

module.exports = { Pool, Client, types };
